import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const sourcePath = resolve("legacy/site.html");
const outputPath = resolve("app/site-html.generated.ts");
const html = await readFile(sourcePath, "utf8");
const generated = [
  "// Generated by scripts/embed-legacy-html.mjs before development and builds.",
  `export const siteHtml = ${JSON.stringify(html)};`,
  "",
].join("\n");

await writeFile(outputPath, generated, "utf8");
